INSERT INTO `impact_stories` (`id`, `title`, `category`, `story_date`, `excerpt`, `image_url`, `full_story`, `is_featured`, `status`, `created_at`, `updated_at`) VALUES
(8, 'First-Ever DRRM Olympics Held at SDO GenTri for Learners', 'DRRM', '2025-08-13', 'The Schools Division Office of General Trias made history as it conducted its first-ever Disaster Risk Reduction and Management (DRRM) Olympics for learners.', '../../shared/uploads/impact-stories/story_68b2e2d927a37.jpg', 'https://www.facebook.com/depedtayogentri/posts/pfbid02qjY4QAxva52ciJ65AwEKYj1QzgiHq8JTKTPZutZ3WRkZc1fDSsdDgia3QdfVP8Hzl', 1, 'active', '2025-08-30 11:39:05', '2025-08-30 11:39:05'),
(9, 'Gentri Storytellers get a fist bump from famous book authors', 'Book', '2025-08-08', 'In a rare and inspiring encounter with renowned authors like Genaro R. Gojo Cruz and Eros Atalia, the Gentri delegates were fortunate to gain valuable insights...', '../../shared/uploads/impact-stories/story_68b2e32e6d6a4.jpg', 'https://www.facebook.com/depedtayogentri/posts/pfbid0WC9w87E1PJrqncBZ2hQdmj8vF8Xdf6haouXZJcPWCrKWYU8RyTBUkFue7haR5offl', 1, 'active', '2025-08-30 11:40:30', '2025-08-30 11:40:30'),
(11, 'LGU Visits School-Evacuation Center: A Trusted Partner in Times of Calamities', 'LGU Visits', '2025-07-22', 'In the spirit of bayanihan, our Local Government Unit (LGU) Mayor Jon-Jon Ferrer, Vice Mayor Jonas Labuguen,  and Councilor Martin Ferrer ( in charge of education) visited Tejero ES  a steadfast partner in sheltering...', '../../shared/uploads/impact-stories/story_68b2e4614a4f7.jpg', 'https://www.facebook.com/depedtayogentri/posts/pfbid0ketV4bb9G9VfVK2DJEFmnFnVZz9gi7TBdY5DqEYkeBo2wvdV4ZSpm7F2vk2sqYS5l', 0, 'active', '2025-08-30 11:45:37', '2025-08-30 11:46:36'),
(12, 'Brigada Eskwela 2025 Along with Partners and Volunteers', 'Brigada Eskwela', '2025-06-15', ' Appreciation to all the amazing volunteers who extended their helping hands and hearts for the opening of classes. Our different schools from SDO General Trias City shine brighter. You are truly our BIDA—Bayani ng Inang Bayan at ng mga Bata!...', '../../shared/uploads/impact-stories/story_68b2e4e33ffd4.jpg', 'https://www.facebook.com/photo.php?fbid=1123278059837247&set=pb.100064651909759.-2207520000&type=3', 1, 'active', '2025-08-30 11:47:47', '2025-08-30 11:47:47');

