INSERT INTO `news_updates` (`id`, `title`, `category`, `news_date`, `excerpt`, `image_url`, `full_content`, `is_featured`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(3, 'updated', 'partnership', '2025-08-29', 'In compliance to Republic Act No. 11106 known as the Filipino Sign Language Act conducts an orientation among school leaders and Special Needs Education (SNED) teachers on the said law. This is to familiarize school heads, teachers with the key provision of RA 11106 including objectives, mandates, and implications for education. To emphasize the role of Filipino Sign Language as the official language of the deaf community in the Philippines. Introduce the necessary tools to support deaf learners, promote cultural sensitivity, and ensure the school compliance with the law.', '../../shared/uploads/impact-stories/story_68b2f6b3eeb0a.jpg', 'https://www.facebook.com/depedtayogentri/posts/pfbid02FQxr29QoBJMoCEV5UCFrvb8epz2DABocb4LpZ4X6mvN62b7RMia5t2PebC1XziMPl', 0, '', 0, '2025-08-30 13:03:47', '2025-08-30 13:38:49'),
(5, 'updated news', 'brigada', '2025-08-22', 'dsadsa', '../../shared/uploads/impact-stories/story_68b2f96a2eaab.jpg', 'dsadsa', 0, '', 0, '2025-08-30 13:15:22', '2025-08-30 13:39:08');

